3 | // Strip ANSI escape codes so the same function handles both TAP and the
4 | // spec-reporter output that Node emits when FORCE_COLOR is set.
5 | function stripAnsi(str) {
6 | 	// eslint-disable-next-line no-control-regex
7 | 	return str.replace(/\x1b\[[0-9;]*m/g, "");
8 | }
9 | 
10 | /**
11 |  * Parse the output of `node --test` (TAP reporter, spec reporter, or the
12 |  * old single-line comma format) and return a one-line summary string.
13 |  *
14 |  * @param {string} output  Combined stdout+stderr from the test run
15 |  * @returns {string}       e.g. "tests: 29 passed, 0 failed"
16 |  *                         or   "tests: 1 passed, 2 failed\n  failing: a, b"
17 |  */
18 | function summarizeTap(output) {
19 | 	var clean = stripAnsi(output);
20 | 
21 | 	var passed = 0;
22 | 	var failed = 0;
23 | 
24 | 	// Format 1 (old single-line): "# tests N, pass P, fail F"
25 | 	var commaMatch = clean.match(/#\s+tests\s+\d+,\s*pass\s+(\d+),\s*fail\s+(\d+)/);
26 | 	if (commaMatch) {
27 | 		passed = parseInt(commaMatch[1], 10);
28 | 		failed = parseInt(commaMatch[2], 10);
29 | 	} else {
30 | 		// Format 2 (TAP multi-line): "# pass N" / "# fail N"
31 | 		// Format 3 (spec-reporter after strip): "ℹ pass N" / "ℹ fail N"
32 | 		var passMatch = clean.match(/(?:#|ℹ)\s+pass\s+(\d+)/);
33 | 		var failMatch = clean.match(/(?:#|ℹ)\s+fail\s+(\d+)/);
34 | 		if (passMatch) passed = parseInt(passMatch[1], 10);
35 | 		if (failMatch) failed = parseInt(failMatch[1], 10);
36 | 	}
37 | 
38 | 	var summary = "tests: " + passed + " passed, " + failed + " failed";
39 | 
40 | 	if (failed > 0) {
41 | 		// TAP failures: "not ok N - name"
42 | 		var notOkLines = clean.match(/^not ok \d+ - .+$/gm) ?? [];
43 | 		var names = notOkLines
44 | 			.slice(0, 3)
45 | 			.map(function (line) { return line.replace(/^not ok \d+ - /, ""); });
46 | 
47 | 		// Spec-reporter failures: lines starting with "✖ name" (after ANSI strip)
48 | 		if (names.length === 0) {
49 | 			var failLines = clean.match(/^✖ .+$/gm) ?? [];
50 | 			names = failLines
51 | 				.slice(0, 3)
52 | 				.map(function (line) { return line.replace(/^✖\s+/, "").replace(/\s*\(.*$/, "").trimEnd(); });
53 | 		}
54 | 
55 | 		if (names.length > 0) {
56 | 			summary += "\n  failing: " + names.join(", ");
57 | 		}
58 | 	}
59 | 
60 | 	return summary;
61 | }
62 | 
63 | module.exports = { summarizeTap };
